const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries for Cambodia and Thailand
  const cambodia = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Cambodia'))
    .geometry();

  const thailand = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Thailand'))
    .geometry();

  // 2. Define time period
  const startDate = '2016-08-01';
  const endDate = '2018-02-28';

  // 3. Load MODIS fire products (Terra and Aqua)
  const modis = ee.ImageCollection('MODIS/006/MOD14A1')
    .merge(ee.ImageCollection('MODIS/006/MYD14A1'))
    .filterDate(startDate, endDate)
    .select('FireMask');

  const collectionSize = modis.size().getInfo();
  console.log('Total MODIS fire images:', collectionSize);

  if (collectionSize === 0) {
    console.log('No fire detection images found in date range.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Create binary fire mask (FireMask values 7-9 indicate fire)
  const fireMask = modis.map(function(img) {
    const fire = img.gte(7).and(img.lte(9));
    return fire.selfMask();
  });

  // 5. Sum all fire detections for Cambodia
  const cambodiaFireSum = fireMask.sum().reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: cambodia,
    scale: 1000,
    maxPixels: 1e9
  });

  const cambodiaCount = cambodiaFireSum.get('FireMask').getInfo();

  // 6. Sum all fire detections for Thailand
  const thailandFireSum = fireMask.sum().reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: thailand,
    scale: 1000,
    maxPixels: 1e9
  });

  const thailandCount = thailandFireSum.get('FireMask').getInfo();

  // 7. Validation
  console.log('Cambodia fire detections:', cambodiaCount);
  console.log('Thailand fire detections:', thailandCount);

  if (cambodiaCount === null || thailandCount === null) {
    console.log('Calculation failed - null result');
    console.log('<answer>C3</answer>');
    return;
  }

  if (isNaN(cambodiaCount) || isNaN(thailandCount)) {
    console.log('Calculation failed - NaN result');
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Compare and answer
  if (cambodiaCount > thailandCount) {
    console.log('Cambodia had more active fire detections');
    console.log('<answer>A</answer>');
  } else {
    console.log('Thailand had equal or more active fire detections');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
